def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: A datetime.time instance.
    :type value: datetime.time
    :return: A string representation of the time suitable for serialization.
    """
    if value is None:
        return None
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    # Try to extract x and y attributes
    try:
        return {"x": value.x, "y": value.y}
    except AttributeError:
        # Fallback: try to index like a tuple or list
        try:
            return {"x": value[0], "y": value[1]}
        except Exception:
            # As a last resort, return the string representation
            return str(value)

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._data.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Try common attribute names that might hold the underlying sequence
    for attr in ("_data", "data", "items"):
        seq = getattr(self, attr, None)
        if seq is not None:
            try:
                return seq.index(key)
            except ValueError:
                # If the key is not present in this sequence, raise the same error
                raise
    # Fallback: iterate over self if it is iterable
    for idx, item in enumerate(self):
        if item == key:
            return idx
    # If we reach here, the key was not found
    raise ValueError(f"{key} is not in list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())
    items = list(self.items())
    result = []
    for key in keys:
        if isinstance(key, int):
            if -len(items) <= key < len(items):
                result.append(items[key][1])
            else:
                raise IndexError(f"Index {key} out of range")
        else:
            if key in self:
                result.append(self[key])
            else:
                raise KeyError(f"Key {key} not found")
    return result

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores its field names in self._keys
    # and the corresponding values in self._data (both sequences).
    if not hasattr(self, "_keys") or not hasattr(self, "_data"):
        raise AttributeError("Record object must have _keys and _data attributes")

    if not keys:
        return {k: v for k, v in zip(self._keys, self._data)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError(f"Index {key} out of bounds for record of length {len(self._data)}")
            field_name = self._keys[key]
            result[field_name] = self._data[key]
        else:
            # Treat as field name
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._data[idx]
            else:
                result[key] = None
    return result

def round_half_to_even(n):
    """
    Round a number to the nearest integer, rounding halves to the nearest even integer.
    This follows the standard "round half to even" (bankers' rounding) behavior.
    """
    return round(n)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = []
    num = ''
    for ch in s:
        if ch.isdigit():
            num += ch
        else:
            if num:
                parts.append(int(num))
                num = ''
    if num:
        parts.append(int(num))
    return tuple(parts)

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        usage = {}
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if typed:
                key = (key,
                       tuple(type(arg) for arg in args),
                       tuple(type(v) for v in kwargs.values()))
            if key in cache:
                usage[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the least frequently used entry
                min_count = min(usage.values())
                # In case of ties, evict the first one found
                for evict_key, count in usage.items():
                    if count == min_count:
                        del cache[evict_key]
                        del usage[evict_key]
                        break
            cache[key] = result
            usage[key] = 1
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Determine the underlying dict-like structure
    if hasattr(self, 'data') and isinstance(self.data, dict):
        d = self.data
    elif hasattr(self, '_dict') and isinstance(self._dict, dict):
        d = self._dict
    elif isinstance(self, dict):
        d = self
    else:
        raise TypeError('popitem: underlying data structure not found')
    if not d:
        raise KeyError('popitem(): dictionary is empty')
    key = next(iter(d))
    value = d.pop(key)
    return key, value

def setdefault(self, key, default=None):
    if key in self:
        return self[key]
    self[key] = default
    return default

def get(self, key, default=None):
    if key in self:
        return self[key]
    return default

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback, os
    def shorten_path(path):
        parts = path.split(os.sep)
        return os.sep.join(parts[-max_path_level:]) if len(parts) > max_path_level else path
    def _format(exc, seen):
        if exc in seen:
            return ['<Recursion detected>']
        seen.add(exc)
        lines = []
        tb = exc.__traceback__
        if tb:
            frames = traceback.extract_tb(tb)
            frames = frames[-max_level:]
            for frame in frames:
                file = shorten_path(frame.filename)
                lines.append(f'  File "{file}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'    {frame.line.strip()}')
        exc_type = type(exc).__name__
        exc_msg = str(exc)
        lines.append(f'{exc_type}: {exc_msg}')
        if exc.__cause__:
            lines.append('Caused by:')
            lines.extend(_format(exc.__cause__, seen))
        elif exc.__context__ and not exc.__suppress_context__:
            lines.append('During handling of the above exception, another exception occurred:')
            lines.extend(_format(exc.__context__, seen))
        return lines
    return '\n'.join(_format(e, set()))

@staticmethod
    def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
