def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            name = name[:-len(suffix)]
    return name

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # If `all` is True, return all instance attributes that are not methods
    # and do not start with an underscore. Otherwise, return only the
    # attributes defined directly on the class (excluding methods and
    # private names).
    if all:
        # Instance attributes
        return [
            name
            for name, value in vars(self).items()
            if not callable(value) and not name.startswith("_")
        ]
    else:
        # Class attributes defined on the class itself
        return [
            name
            for name, value in self.__class__.__dict__.items()
            if not callable(value) and not name.startswith("_")
        ]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        # Expand tuples or lists, but treat other iterables (e.g. strings) as
        # individual arguments.
        if isinstance(arg, (list, tuple)):
            _normalizeargs(arg, output)
        else:
            output.append(arg)
    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    return not _c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    if getattr(self, "initial_value", None) is not None:
        # If an initial value was provided, set all bins to that value
        # Preserve the current number of bins
        if hasattr(self, "bins") and self.bins is not None:
            self.bins = [self.initial_value] * len(self.bins)
        else:
            # Fallback: create a single bin with the initial value
            self.bins = [self.initial_value]
    else:
        # No initial value: use the factory method to create bins
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []

    if header is not None:
        lines.append(header)

    for point in self.points:
        # Try to extract coordinate and value from the point
        if hasattr(point, "coordinate") and hasattr(point, "value"):
            coord = point.coordinate
            val = point.value
        else:
            try:
                coord, val = point
            except Exception:
                # If point is not iterable, treat the whole point as coordinate
                coord, val = point, None

        # Convert coordinate to a list of strings
        if isinstance(coord, (str, bytes)):
            coord_parts = [coord]
        elif hasattr(coord, "__iter__"):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]

        # Convert value to a list of strings
        if val is None:
            val_parts = []
        elif isinstance(val, (str, bytes)):
            val_parts = [val]
        elif hasattr(val, "__iter__"):
            val_parts = [str(v) for v in val]
        else:
            val_parts = [str(val)]

        line = separator.join(coord_parts + val_parts)
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    err_indices = getattr(self, "_err_indices", None)
    if err_indices is None:
        raise AttributeError("Attribute '_err_indices' not found.")
    # If err_indices is a mapping from coordinate name to indices
    if isinstance(err_indices, dict):
        if coord_name not in err_indices:
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")
        return err_indices[coord_name]
    # If err_indices is a sequence, assume it aligns with a list of coordinate names
    if isinstance(err_indices, (list, tuple)):
        coord_names = getattr(self, "_coord_names", None)
        if coord_names is None:
            raise AttributeError("Attribute '_coord_names' not found.")
        try:
            idx = coord_names.index(coord_name)
        except ValueError:
            raise KeyError(f"Coordinate '{coord_name}' not found in coordinate names.")
        return err_indices[idx]
    # Unsupported type
    raise TypeError("Unsupported type for '_err_indices' attribute.")

def _update_context(self, context):
    # Ensure context.error exists and is a dict
    if not hasattr(context, "error") or context.error is None:
        context.error = {}
    if not isinstance(context.error, dict):
        context.error = {}
    # Retrieve fields and coordinates from the graph
    fields = getattr(self, "fields", [])
    coordinates = getattr(self, "coordinates", [])
    # Map coordinate names to x, y, z (first three coordinates)
    coord_map = {}
    for idx, coord in enumerate(coordinates[:3]):
        if idx == 0:
            coord_map[coord] = "x"
        elif idx == 1:
            coord_map[coord] = "y"
        elif idx == 2:
            coord_map[coord] = "z"
    # Iterate over fields to find error fields
    for i, field in enumerate(fields):
        if field.startswith("error_"):
            rest = field[len("error_") :]
            parts = rest.split("_")
            if len(parts) >= 2:
                coord_name = parts[0]
                suffix = "_".join(parts[1:])
                coord = coord_map.get(coord_name)
                if coord:
                    key = f"{coord}_{suffix}"
                    context.error[key] = {"index": i}

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Helper to check if an object is a FillRequest
    def _is_fill_request(obj):
        try:
            return isinstance(obj, FillRequest)
        except NameError:
            return False

    # Helper to check if an object is a Source
    def _is_source(obj):
        try:
            return isinstance(obj, Source)
        except NameError:
            return False

    # If seq itself is a FillRequest, return True
    if _is_fill_request(seq):
        return True

    # If seq is a Source (or a sequence of Sources), return False
    if _is_source(seq):
        return False
    # If seq is an iterable (but not a string/bytes), check its elements
    if isinstance(seq, (list, tuple, set)):
        # If all elements are Source, treat as Source sequence
        if seq and all(_is_source(x) for x in seq):
            return False
        # If any element is a FillRequest, return True
        if any(_is_fill_request(x) for x in seq):
            return True
        return False

    # For other iterables (e.g., generators), attempt to iterate safely
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    else:
        # Avoid treating strings or bytes as iterables of characters
        if isinstance(seq, (str, bytes)):
            return False
        # Check elements
        has_fill = False
        all_source = True
        for item in iterator:
            if _is_fill_request(item):
                has_fill = True
            if not _is_source(item):
                all_source = False
        if all_source:
            return False
        return has_fill

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return (
        hasattr(obj, "fill") and callable(getattr(obj, "fill", None))
        and hasattr(obj, "request") and callable(getattr(obj, "request", None))
    )

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return callable(getattr(obj, 'run', None))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return (
        hasattr(obj, "fill") and callable(getattr(obj, "fill")) and
        hasattr(obj, "compute") and callable(getattr(obj, "compute"))
    )

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper to determine if we should recurse
    def _should_recurse(lvl):
        return lvl != 0

    result = {}
    for key, val in d1.items():
        if key not in d2:
            # Key only in d1: include it
            result[key] = val
        else:
            # Key in both
            val2 = d2[key]
            # If both values are dicts and we are allowed to recurse
            if isinstance(val, dict) and isinstance(val2, dict) and _should_recurse(level):
                # Determine new recursion level
                new_level = -1 if level == -1 else level - 1
                subdiff = difference(val, val2, new_level)
                if subdiff:
                    result[key] = subdiff
            else:
                # For level 0 we skip any differences
                if level == 0:
                    continue
                # For other levels, include if values differ
                if val != val2:
                    result[key] = val
    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has an observer_schema dictionary
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    # Helper to deep‑copy a nested dictionary
    def _deep_copy(d):
        return {k: _deep_copy(v) if isinstance(v, dict) else v for k, v in d.items()}

    # Default schema to apply to resources without a custom schema
    default_schema = {
        "metadata": {
            "name": {"type": "string"},
            "namespace": {"type": "string"},
            "labels": {"type": "object"},
            "annotations": {"type": "object"},
        },
        "spec": {"type": "object"},
        "status": {"type": "object"},
    }

    # Iterate over all resources in the manifest
    for resource in app.spec.manifest:
        # Extract the kind of the resource
        kind = None
        if isinstance(resource, dict):
            kind = resource.get("kind")
        else:
            kind = getattr(resource, "kind", None)

        # Skip if kind is not defined or already has a custom schema
        if not kind or kind in app.spec.observer_schema:
            continue

        # Assign a deep copy of the default schema to this kind
        app.spec.observer_schema[kind] = _deep_copy(default_schema)

    return app.spec.observer_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Determine validity status from common attribute names
    status = None
    if hasattr(self, 'valid'):
        status = self.valid
    elif hasattr(self, 'is_valid'):
        status = self.is_valid
    elif hasattr(self, 'validity'):
        status = self.validity
    else:
        try:
            status = bool(self)
        except Exception:
            status = None

    if status is True:
        status_text = 'VALID'
    elif status is False:
        status_text = 'INVALID'
        if hasattr(self, 'errors'):
            err = self.errors
            if isinstance(err, (list, tuple)):
                err_text = ', '.join(map(str, err))
            else:
                err_text = str(err)
            status_text += f": {err_text}"
    else:
        status_text = 'UNKNOWN'

    return f"{prefix}{status_text}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Assume the validation log is stored in an attribute named `log`
    # which is an iterable of log entries. Each entry is converted to a string.
    log_entries = getattr(self, 'log', [])
    if not log_entries:
        return ''
    return '\n'.join(f"{prefix}{str(entry)}" for entry in log_entries)

def validate(self, inventory, extract_spec_version=False):
        """
        Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Determine the spec version to use
        spec_version = self.spec_version
        if extract_spec_version:
            type_value = inventory.get("type")
            if type_value:
                # Map known type values to spec versions
                type_to_version = {
                    "inventory": "1.0",
                    "inventory_v2": "2.0",
                    "inventory_v3": "3.0",
                }
                spec_version = type_to_version.get(type_value, self.spec_version)

        # If we still don't have a spec version, raise an error
        if not spec_version:
            raise ValueError("Spec version could not be determined.")

        # Validate the spec version is supported
        supported_versions = {"1.0", "2.0", "3.0"}
        if spec_version not in supported_versions:
            raise ValueError(f"Unsupported spec version: {spec_version}")

        # Perform version-specific validation checks
        if spec_version == "1.0":
            if "hosts" not in inventory:
                raise ValueError("Inventory missing required 'hosts' key for spec version 1.0.")
        elif spec_version == "2.0":
            if "groups" not in inventory:
                raise ValueError("Inventory missing required 'groups' key for spec version 2.0.")
        elif spec_version == "3.0":
            if "metadata" not in inventory:
                raise ValueError("Inventory missing required 'metadata' key for spec version 3.0.")

        # If all checks pass, return True
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize digests_used to a set
    digests_needed = set(digests_used)

    # Collect all digests from the manifest(s)
    manifest_digests = set()

    # Helper to process a single file path
    def _process_file(path):
        try:
            with open(path, "r") as f:
                for line in f:
                    digest = line.strip()
                    if digest:
                        manifest_digests.add(digest)
        except FileNotFoundError:
            raise FileNotFoundError(f"Manifest file {path} not found.")

    # Handle different possible types for manifest_files
    if isinstance(manifest_files, dict):
        # Assume values are either file paths or iterables of digests
        for value in manifest_files.values():
            if isinstance(value, str):
                _process_file(value)
            else:
                for d in value:
                    manifest_digests.add(str(d).strip())
    elif isinstance(manifest_files, (list, tuple)):
        for item in manifest_files:
            if isinstance(item, str):
                _process_file(item)
            else:
                for d in item:
                    manifest_digests.add(str(d).strip())
    else:
        # Assume a single file path
        _process_file(manifest_files)

    # Check that all needed digests are present in the manifest
    missing = digests_needed - manifest_digests
    if missing:
        raise ValueError(
            f"Missing digests in manifest: {', '.join(sorted(missing))}"
        )

    # Optionally, warn about digests present in the manifest but not used
    unused = manifest_digests - digests_needed
    if unused:
        # In many contexts this might be a warning rather than an error.
        # Here we simply ignore it, but you could log or raise if desired.
        pass

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same class as self")

    # Ensure both objects have a 'version' attribute
    if not hasattr(self, "version"):
        raise AttributeError("self object lacks a 'version' attribute")
    if not hasattr(prior, "version"):
        raise AttributeError("prior object lacks a 'version' attribute")

    # Prior version must be strictly older
    if prior.version >= self.version:
        raise ValueError(
            f"prior version {prior.version} is not older than current version {self.version}"
        )

    # If inventory data is stored in a dictionary called 'inventory',
    # ensure that prior's inventory is a subset of the current inventory.
    if hasattr(self, "inventory") and hasattr(prior, "inventory"):
        # Check that all items in prior exist in current
        missing_items = set(prior.inventory) - set(self.inventory)
        if missing_items:
            raise ValueError(
                f"prior inventory contains items not present in current inventory: {missing_items}"
            )
        # Optionally, check that quantities in current are at least as large
        for item, qty in prior.inventory.items():
            if self.inventory[item] < qty:
                raise ValueError(
                    f"current inventory has less quantity for item '{item}' "
                    f"({self.inventory[item]}) than prior ({qty})"
                )
    # If no 'inventory' attribute, skip subset check
    return None

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure inventory is a mapping from version to a mapping of logical_path -> content_file
    result = {}

    # Get the base mapping for the requested version
    base_map = inventory.get(version)
    if base_map is None:
        return result

    # Normalize base_map to a dict if it is a list of entries
    if isinstance(base_map, list):
        temp = {}
        for entry in base_map:
            lp = entry.get("logical_path")
            cf = entry.get("content_file")
            if lp is not None:
                temp[lp] = cf
        base_map = temp

    # Initialize result with the base version's mapping
    for logical_path, content_file in base_map.items():
        result.setdefault(logical_path, set()).add(content_file)

    # Include duplicates from later versions
    for v in sorted(inventory.keys()):
        if v <= version:
            continue
        later_map = inventory.get(v)
        if later_map is None:
            continue

        # Normalize later_map if it is a list of entries
        if isinstance(later_map, list):
            temp = {}
            for entry in later_map:
                lp = entry.get("logical_path")
                cf = entry.get("content_file")
                if lp is not None:
                    temp[lp] = cf
            later_map = temp

        for logical_path in result:
            if logical_path in later_map:
                result[logical_path].add(later_map[logical_path])

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    # Determine the list of entries to validate
    if "files" in fixity:
        entries = fixity["files"]
        if not isinstance(entries, list):
            raise ValueError("'files' in fixity block must be a list.")
    else:
        # Assume a mapping of path -> hash
        entries = [{"path": p, "hash": h} for p, h in fixity.items()]
    seen_paths = set()
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("Each fixity entry must be a dictionary.")
        if "path" not in entry:
            raise ValueError("Each fixity entry must contain a 'path' key.")
        path = entry["path"]
        if path not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{path}'.")
        if path in seen_paths:
            raise ValueError(f"Duplicate fixity entry for file '{path}'.")
        seen_paths.add(path)
        if "hash" not in entry:
            raise ValueError(f"Fixity entry for '{path}' missing 'hash' key.")
        if not isinstance(entry["hash"], str):
            raise ValueError(f"Hash for '{path}' must be a string.")
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except Exception:
        return []

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    if not hasattr(self, 'renditions'):
        self.renditions = {}
