def add_asset(self, basename, file_path):
    if not hasattr(self, 'assets'):
        self.assets = {}
    idx = max(file_path.rfind('/'), file_path.rfind('\\'))
    directory = file_path[:idx] if idx != -1 else ''
    directory = directory.rstrip('/\\')
    exts = ['.tiff', '.jpg', '.png']
    for ext in exts:
        key = f"{basename}{ext}"
        if directory:
            value = f"{directory}/{basename}{ext}"
        else:
            value = f"{basename}{ext}"
        self.assets[key] = value

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        return content
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            results = node.xpath(xpath)
        except Exception:
            continue
        if results:
            value = results[0]
            if isinstance(value, str):
                return value.strip()
            # If it's an element, try to get its text content
            text = getattr(value, 'text', None)
            if text is not None:
                return text.strip()
            # Some libraries provide a text_content() method
            text_content = getattr(value, 'text_content', None)
            if callable(text_content):
                return text_content().strip()
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}:"]
    for key, value in sorted(self.__dict__.items()):
        if isinstance(value, (list, tuple)):
            lines.append(f"{indent_str}  {key}:")
            for item in value:
                if hasattr(item, 'pretty'):
                    lines.append(item.pretty(indent + 4, debug))
                else:
                    lines.append(f"{indent_str}    {repr(item)}")
        elif isinstance(value, dict):
            lines.append(f"{indent_str}  {key}:")
            for k, v in sorted(value.items()):
                if hasattr(v, 'pretty'):
                    lines.append(f"{indent_str}    {k}:")
                    lines.append(v.pretty(indent + 6, debug))
                else:
                    lines.append(f"{indent_str}    {k}: {repr(v)}")
        elif hasattr(value, 'pretty'):
            lines.append(f"{indent_str}  {key}:")
            lines.append(value.pretty(indent + 4, debug))
        else:
            lines.append(f"{indent_str}  {key}: {repr(value)}")
    if debug:
        lines.append(f"{indent_str}  <debug id={id(self)}>")
    return '\n'.join(lines)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions for expression manipulation
    def is_op(expr, op):
        return isinstance(expr, tuple) and expr and expr[0] == op

    def get_left(expr):
        return expr[1]

    def get_right(expr):
        return expr[2]

    def is_neg(expr):
        return isinstance(expr, tuple) and expr and expr[0] == '~'

    def get_neg(expr):
        return expr[1] if is_neg(expr) else None

    def simplify_pair(e, f):
        # Absorption: A & (A | B) = A, A | (A & B) = A
        if is_op(f, '|') and (f[1] == e or f[2] == e):
            return e
        if is_op(f, '&') and (f[1] == e or f[2] == e):
            return e
        # Negative absorption: A & (~A | B) = A & B
        if is_op(f, '|'):
            if is_neg(f[1]) and get_neg(f[1]) == e:
                return ('&', e, f[2])
            if is_neg(f[2]) and get_neg(f[2]) == e:
                return ('&', e, f[1])
        # Negative absorption: A | (~A & B) = A | B
        if is_op(f, '&'):
            if is_neg(f[1]) and get_neg(f[1]) == e:
                return ('|', e, f[2])
            if is_neg(f[2]) and get_neg(f[2]) == e:
                return ('|', e, f[1])
        # Reverse patterns: f is A, e is pattern
        if is_op(e, '|') and (e[1] == f or e[2] == f):
            return f
        if is_op(e, '&') and (e[1] == f or e[2] == f):
            return f
        if is_op(e, '|'):
            if is_neg(e[1]) and get_neg(e[1]) == f:
                return ('&', f, e[2])
            if is_neg(e[2]) and get_neg(e[2]) == f:
                return ('&', f, e[1])
        if is_op(e, '&'):
            if is_neg(e[1]) and get_neg(e[1]) == f:
                return ('|', f, e[2])
            if is_neg(e[2]) and get_neg(e[2]) == f:
                return ('|', f, e[1])
        return None

    # Iteratively apply simplifications until no changes
    current = list(args)
    while True:
        changed = False
        new_args = []
        used = [False] * len(current)
        for i in range(len(current)):
            if used[i]:
                continue
            e = current[i]
            simplified = None
            for j in range(i + 1, len(current)):
                if used[j]:
                    continue
                f = current[j]
                simplified = simplify_pair(e, f)
                if simplified is not None:
                    used[i] = used[j] = True
                    changed = True
                    break
            if not used[i]:
                new_args.append(e)
            if simplified is not None:
                new_args.append(simplified)
        # Remove duplicates while preserving order
        seen = set()
        unique_args = []
        for expr in new_args:
            if expr not in seen:
                unique_args.append(expr)
                seen.add(expr)
        current = unique_args
        if not changed:
            break
    return current

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to read a VERSION file in the current directory
    try:
        with open('VERSION', 'r') as f:
            version = f.read().strip()
        # If the file contains a version string, return it
        if version:
            return {'version': version, 'full-revisionid': 'unknown'}
    except Exception:
        pass
    # Fallback to a default version
    return {'version': '0.0.0', 'full-revisionid': 'unknown'}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Convert pieces to a list of string parts
    if isinstance(pieces, dict):
        # Expected keys in order: major, minor, patch, pre, build
        order = ["major", "minor", "patch", "pre", "build"]
        parts = [str(pieces[k]) for k in order if k in pieces]
    else:
        parts = [str(p) for p in pieces]

    # Helper to safely get part by index
    def get(idx, default=""):
        return parts[idx] if idx < len(parts) else default

    if style == "full":
        return ".".join(parts)
    if style == "short":
        return ".".join(parts[:2])
    if style == "pretty":
        return "v" + ".".join(parts)
    if style == "semver":
        major = get(0)
        minor = get(1)
        patch = get(2)
        pre = get(3)
        build = get(4)
        s = f"{major}.{minor}.{patch}"
        if pre:
            s += f"-{pre}"
        if build:
            s += f"+{build}"
        return s
    if style == "pep440":
        major = get(0)
        minor = get(1)
        patch = get(2)
        pre = get(3)
        build = get(4)
        s = f"{major}.{minor}.{patch}"
        if pre:
            s += f"{pre}"
        if build:
            s += f"+{build}"
        return s
    raise ValueError(f"Unknown style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '.' if '+' in pieces else '+'

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    if method is None:
        def decorator(func):
            register_vcs_handler._registry[vcs] = func
            return func
        return decorator
    register_vcs_handler._registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Retrieve the collection of objects to validate.  The class may expose
    # them via an attribute named ``objects`` or ``items``; fall back to an
    # empty list if neither is present.
    objects = getattr(self, "objects", None) or getattr(self, "items", [])

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Object-level validation
        if validate_objects:
            try:
                # Prefer a custom ``validate`` method if present
                if hasattr(obj, "validate") and callable(obj.validate):
                    is_valid = bool(obj.validate())
                # Fallback to a generic ``is_valid`` attribute
                elif hasattr(obj, "is_valid"):
                    is_valid = bool(obj.is_valid)
                # If no validation hook, assume valid
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[validate_hierarchy] Validation error for {obj!r}: {exc}")

        # Digest check
        if check_digests and is_valid:
            try:
                if hasattr(obj, "check_digest") and callable(obj.check_digest):
                    digest_ok = bool(obj.check_digest())
                elif hasattr(obj, "digest") and hasattr(obj, "expected_digest"):
                    digest_ok = (obj.digest == obj.expected_digest)
                else:
                    digest_ok = True  # No digest information, assume OK
            except Exception as exc:
                digest_ok = False
                if show_warnings:
                    print(f"[validate_hierarchy] Digest check error for {obj!r}: {exc}")

            if not digest_ok:
                is_valid = False

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return version
    parts = version.split('.')
    last = parts[-1]
    if last.isdigit():
        width = len(last)
        new_num = str(int(last) + 1)
        if len(new_num) < width:
            new_num = new_num.zfill(width)
        parts[-1] = new_num
    else:
        # If the last part is not purely numeric, just append a suffix
        parts[-1] = f"{last}1"
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure required attributes exist
    if not hasattr(self, "root_inventory"):
        raise AttributeError("Instance must have a 'root_inventory' attribute")
    if not hasattr(self, "base_path"):
        raise AttributeError("Instance must have a 'base_path' attribute")

    # Store differences: {content_name: [(version, inv_digest, root_digest), ...]}
    self.different_digests = {}

    for version_dir in version_dirs:
        # Path to the inventory file for this version
        inv_path = os.path.join(self.base_path, version_dir, "inventory.json")

        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory for version '{version_dir}' at {inv_path}")

        # Load the inventory
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory for '{version_dir}': {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory for '{version_dir}' must be a mapping of content to digest")

        # Validate each entry
        for name, digest in inv.items():
            if name not in self.root_inventory:
                raise KeyError(f"Content '{name}' in inventory '{version_dir}' not found in root inventory")

            root_digest = self.root_inventory[name]
            if digest != root_digest:
                self.different_digests.setdefault(name, []).append(
                    (version_dir, digest, root_digest)
                )

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"error: path does not exist: {path}"

    if os.path.isfile(path):
        return "file"

    # path is a directory
    # Find a file that matches the pattern "0=*"
    namaste_file = None
    for entry in os.listdir(path):
        if entry.startswith("0="):
            full = os.path.join(path, entry)
            if os.path.isfile(full):
                namaste_file = full
                break

    if not namaste_file:
        return f"error: no namaste file found in directory: {path}"

    # Read the namaste file content
    try:
        with open(namaste_file, "r", encoding="utf-8") as f:
            content = f.read().strip()
    except Exception as e:
        return f"error: cannot read namaste file: {e}"

    # Try to infer type from content
    # Some implementations may include "OCFL" and a type hint
    if "OCFL" in content:
        if "Object" in content:
            return "object"
        if "Root" in content:
            return "root"

    # Fallback heuristics if content is ambiguous
    # Root typically contains an "objects" subdirectory
    if os.path.isdir(os.path.join(path, "objects")):
        return "root"
    # Object typically contains an "inventory.json" file
    if os.path.isfile(os.path.join(path, "inventory.json")):
        return "object"

    return f"error: cannot determine type for directory: {path}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if bug_ids is None:
        return params
    # If bug_ids is a string, use it directly
    if isinstance(bug_ids, str):
        params['ids'] = bug_ids
    else:
        try:
            # Try to treat bug_ids as an iterable
            ids_list = list(bug_ids)
            if not ids_list:
                # Empty iterable: remove any existing 'ids' key
                params.pop('ids', None)
            else:
                params['ids'] = ','.join(str(i) for i in ids_list)
        except TypeError:
            # Not iterable: treat as a single id
            params['ids'] = str(bug_ids)
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def merge_mapping_nodes(node1, node2):
        # node1 and node2 are MappingNode instances
        dict1 = {}
        for k_node, v_node in node1.value:
            dict1[k_node.value] = (k_node, v_node)
        dict2 = {}
        for k_node, v_node in node2.value:
            dict2[k_node.value] = (k_node, v_node)
        merged_list = []
        # keys from first mapping
        for key in dict1:
            k_node1, v_node1 = dict1[key]
            if key in dict2:
                k_node2, v_node2 = dict2[key]
                if getattr(v_node1, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(v_node2, 'tag', None) == 'tag:yaml.org,2002:map':
                    merged_v = merge_mapping_nodes(v_node1, v_node2)
                else:
                    merged_v = v_node2
                merged_list.append((k_node1, merged_v))
            else:
                merged_list.append((k_node1, v_node1))
        # keys only in second mapping
        for key in dict2:
            if key not in dict1:
                k_node2, v_node2 = dict2[key]
                merged_list.append((k_node2, v_node2))
        # create a new MappingNode with the same tag as node1
        return type(node1)(node1.tag, merged_list)

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            if getattr(value_node, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(existing_value_node, 'tag', None) == 'tag:yaml.org,2002:map':
                merged_value = merge_mapping_nodes(existing_value_node, value_node)
            else:
                merged_value = value_node
            merged[key] = (existing_key_node, merged_value)
        else:
            merged[key] = (key_node, value_node)
    return [(k, v) for k, (k_node, v) in merged.items()]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Collect all option strings from the parser's actions
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flags for this action
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import OrderedDict

    def merge_mapping_nodes(existing, new):
        # existing and new are MappingNode instances
        merged_list = list(existing.value)  # shallow copy
        # Build index map for existing keys
        existing_index = {k.value: i for i, (k, _) in enumerate(merged_list)}
        for k_new, v_new in new.value:
            if k_new.value in existing_index:
                idx = existing_index[k_new.value]
                _, v_existing = merged_list[idx]
                # If both are MappingNode, merge recursively
                if isinstance(v_existing, type(existing)) and isinstance(v_new, type(existing)):
                    merged_val = merge_mapping_nodes(v_existing, v_new)
                else:
                    merged_val = v_new
                merged_list[idx] = (k_new, merged_val)
            else:
                merged_list.append((k_new, v_new))
        return type(existing)(tag=existing.tag, value=merged_list)

    result = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key in result:
            existing_value = result[key]
            if isinstance(existing_value, type(value_node)) and isinstance(value_node, type(existing_value)):
                # Both are MappingNode
                merged_value = merge_mapping_nodes(existing_value, value_node)
                result[key] = merged_value
            else:
                # Non-mapping or different types: last wins
                result[key] = value_node
        else:
            result[key] = value_node
    # Preserve original key nodes order
    return [(key_node, result[key_node.value]) for key_node, _ in nodes if key_node.value in result]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings (e.g., ['-h', '--help'])
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    size = size.strip()
    if not size:
        raise ValueError("size string is empty")

    # Define unit multipliers (decimal, not binary)
    units = {
        'k': 10 ** 3,
        'm': 10 ** 6,
        'g': 10 ** 9,
        't': 10 ** 12,
        'p': 10 ** 15,
        'e': 10 ** 18,
        'z': 10 ** 21,
        'y': 10 ** 24,
    }

    # Check if last character is a unit letter
    if size[-1].isalpha():
        unit = size[-1].lower()
        if unit not in units:
            raise ValueError(f"Unknown unit '{size[-1]}' in size string")
        try:
            number = float(size[:-1].strip())
        except ValueError as exc:
            raise ValueError(f"Invalid numeric value in size string: {size}") from exc
        return int(round(number * units[unit]))
    else:
        # No unit, interpret as plain number of bytes
        try:
            number = float(size)
        except ValueError as exc:
            raise ValueError(f"Invalid numeric value in size string: {size}") from exc
        return int(round(number))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    for key, val in url_args.items():
        if val is None:
            continue
        placeholder_braces = f"{{{key}}}"
        placeholder_colon = f":{key}"
        url = url.replace(placeholder_braces, str(val))
        url = url.replace(placeholder_colon, str(val))
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if not isinstance(val, str):
        return False
    return val.strip().lower() in {"none", "null", "nil"}

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    if base <= 0:
        raise ValueError("Alphabet must contain at least one character")
    if base == 1:
        # Unary representation: repeat the single symbol
        if number < 0:
            raise ValueError("Negative numbers cannot be represented in base 1")
        if number == 0:
            digits = [alphabet[0]]
        else:
            digits = [alphabet[0]] * number
    else:
        sign = ''
        if number < 0:
            sign = '-'
            number = -number
        if number == 0:
            digits = [alphabet[0]]
        else:
            digits = []
            while number > 0:
                digits.append(alphabet[number % base])
                number //= base
            digits.reverse()
    if padding is not None:
        pad_len = padding - len(digits)
        if pad_len > 0:
            digits = [alphabet[0]] * pad_len + digits
    return (sign if base != 1 else '') + ''.join(digits) if base != 1 else ''.join(digits)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subs = set(cls.__subclasses__())
    for sub in list(subs):
        subs.update(subclasses(sub))
    return subs

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    base = len(alphabet)
    # Create a mapping from character to its numeric value
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not in alphabet")
        result = result * base + char_to_value[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    return re.sub(r"^['\"]|['\"]$", "", name)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        return None
    if freq.lower() == "always":
        return None

    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    num_str, unit = parts
    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{num_str}'")

    unit = unit.lower()
    # Normalize unit to singular form
    if unit.endswith('s'):
        unit = unit[:-1]

    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
    }

    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{unit}'")

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to get all possible addresses
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be localhost
        return False

    for family, _, _, _, sockaddr in addrinfo:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            # IPv4 loopback addresses start with 127.
            if ip == "127.0.0.1" or ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # IPv6 loopback address
            if ip == "::1" or ip.startswith("::ffff:127.0.0.1"):
                return True

    return False

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if strip:
        pattern = pattern.strip()
    escaped = re.escape(pattern)
    return re.compile(f'^{escaped}$')

def is_ipv4(target):
    """ Test if IPv4 address or not """
    if target is None:
        return False
    if isinstance(target, ipaddress.IPv4Address):
        return True
    try:
        ipaddress.IPv4Address(str(target))
        return True
    except Exception:
        return False

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        # Find all subjects that are not objects
        subjects = set()
        objects = set()
        for s, p, o in graph.triples((None, prop, None)):
            subjects.add(s)
            objects.add(o)
        return subjects - objects
    else:
        # Find roots reachable from the given set of nodes
        roots_set: Set["Node"] = set()
        visited: Set["Node"] = set()
        stack = list(roots)
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            parents = list(graph.objects(node, prop))
            if not parents:
                roots_set.add(node)
            else:
                for parent in parents:
                    if parent not in visited:
                        stack.append(parent)
        return roots_set

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        return yaml.safe_dump(obj, allow_unicode=True)
    else:
        return yaml.safe_dump(obj, Dumper=dumper, allow_unicode=True)

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        return cls([])
    bookmarks = []
    for raw in values:
        try:
            bookmark = Bookmark.from_raw_value(raw)
            bookmarks.append(bookmark)
        except Exception:
            # Skip entries that cannot be parsed
            continue
    return cls(bookmarks)

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute integral if needed
    def _compute_integral():
        # Try a dedicated method first
        if hasattr(self, "_integral") and callable(getattr(self, "_integral")):
            return self._integral()
        # Fallback: sum of bin contents times bin widths
        if hasattr(self, "_bins") and hasattr(self, "_bin_edges"):
            bins = self._bins
            edges = self._bin_edges
            # Compute widths
            widths = [edges[i + 1] - edges[i] for i in range(len(edges) - 1)]
            # If bins is a list or array-like
            try:
                return sum(b * w for b, w in zip(bins, widths))
            except Exception:
                # In case bins is a numpy array
                return (bins * widths).sum()
        raise AttributeError("Cannot compute integral: missing _integral, _bins, or _bin_edges")

    # If no target scale is given, return the current scale
    if other is None:
        if recompute or getattr(self, "_scale", None) is None:
            self._scale = _compute_integral()
        return self._scale

    # Rescaling requested
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric type")

    # Ensure current scale is known
    if getattr(self, "_scale", None) is None:
        self._scale = _compute_integral()

    # Cannot rescale a histogram with zero scale
    if self._scale == 0:
        raise ValueError("Cannot rescale histogram with zero scale")

    factor = other / self._scale

    # Scale bin contents
    if hasattr(self, "_bins"):
        bins = self._bins
        if isinstance(bins, list):
            self._bins = [x * factor for x in bins]
        else:
            # Assume numpy array or similar
            self._bins *= factor

    # Scale errors if present
    if hasattr(self, "_errors"):
        errors = self._errors
        if isinstance(errors, list):
            self._errors = [x * factor for x in errors]
        else:
            self._errors *= factor

    # Update stored scale
    self._scale = other
    # No return value when rescaling
    return None

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate is a subclass or instance of iface, or if it
    implements all attributes/methods defined on iface.  If *tentative* is
    True, the check is performed but missing attributes simply cause a
    False return rather than raising an exception.
    """
    # Handle None candidate
    if candidate is None:
        return False

    # If iface is a tuple of interfaces, succeed if any one matches
    if isinstance(iface, tuple):
        for base in iface:
            if verifyClass(base, candidate, tentative):
                return True
        return False

    # Determine if candidate is a class or an instance
    is_class = isinstance(candidate, type)

    # Quick subclass/instance check
    try:
        if is_class:
            if issubclass(candidate, iface):
                return True
        else:
            if isinstance(candidate, iface):
                return True
    except TypeError:
        # In case iface is not a class or tuple
        pass

    # Gather attributes from iface, ignoring dunder methods
    iface_attrs = [name for name in dir(iface) if not name.startswith("__")]

    # Function to check a single attribute on the candidate
    def has_attr(name):
        if is_class:
            return hasattr(candidate, name)
        else:
            return hasattr(candidate, name)

    def is_callable(name):
        try:
            attr = getattr(candidate, name) if is_class else getattr(candidate, name)
            return callable(attr)
        except Exception:
            return False

    # Verify each attribute
    for name in iface_attrs:
        if not has_attr(name):
            return False
        # If the attribute is a method in iface, ensure candidate's is callable
        iface_attr = getattr(iface, name)
        if callable(iface_attr):
            if not is_callable(name):
                return False

    return True

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self.cache:
        raise KeyError('popitem from an empty LRUCache')
    return self.cache.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
