def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    See the module documentation for details on supported formats.
    """
    import re
    from datetime import datetime, date
    from dateutil.tz import tzoffset, tzutc

    # Accept a stream or bytes
    if hasattr(dt_str, "read"):
        dt_str = dt_str.read()
    if isinstance(dt_str, bytes):
        dt_str = dt_str.decode("ascii")
    dt_str = dt_str.strip()

    if not dt_str:
        raise ValueError("Empty datetime string")

    # Split date and time
    if "T" in dt_str:
        date_part, time_part = dt_str.split("T", 1)
    else:
        date_part, time_part = dt_str, None

    # ---------- Parse date ----------
    # Week format
    week_re = re.compile(r"^(?P<year>\d{4})-?W(?P<week>\d{2})(?:-?(?P<weekday>\d))?$")
    m = week_re.match(date_part)
    if m:
        if time_part:
            raise ValueError("Week dates cannot have a time component")
        year = int(m.group("year"))
        week = int(m.group("week"))
        weekday = m.group("weekday")
        if weekday is None:
            weekday = 1  # default to Monday
        else:
            weekday = int(weekday)
        try:
            d = date.fromisocalendar(year, week, weekday)
        except ValueError as exc:
            raise ValueError(f"Invalid ISO week date: {date_part}") from exc
        year, month, day = d.year, d.month, d.day
    else:
        # Common date formats
        date_re = re.compile(
            r"^(?P<year>\d{4})-?(?P<month>\d{2})?(-?(?P<day>\d{2}))?$"
        )
        m = date_re.match(date_part)
        if not m:
            raise ValueError(f"Unrecognized date format: {date_part}")
        year = int(m.group("year"))
        month = m.group("month")
        day = m.group("day")
        month = int(month) if month else 1
        day = int(day) if day else 1
        try:
            d = date(year, month, day)
        except ValueError as exc:
            raise ValueError(f"Invalid date: {date_part}") from exc
        year, month, day = d.year, d.month, d.day

    # ---------- Parse time ----------
    hour = minute = second = microsecond = 0
    tzinfo = None

    if time_part:
        # Regex to capture time and optional timezone
        time_tz_re = re.compile(
            r"""
            ^
            (?P<hour>\d{2})
            (?::?(?P<minute>\d{2}))?
            (?::?(?P<second>\d{2}))?
            (?:[.,](?P<fraction>\d{1,6}))?
            (?P<tz>Z|[+-]\d{2}(:?\d{2})?)?
            $
            """,
            re.VERBOSE,
        )
        m = time_tz_re.match(time_part)
        if not m:
            raise ValueError(f"Unrecognized time format: {time_part}")

        hour = int(m.group("hour"))
        minute = int(m.group("minute")) if m.group("minute") else 0
        second = int(m.group("second")) if m.group("second") else 0
        fraction = m.group("fraction")
        if fraction:
            if len(fraction) > 6:
                raise ValueError("Fractional seconds must have at most 6 digits")
            microsecond = int(fraction.ljust(6, "0"))
        else:
            microsecond = 0

        # Midnight special case
        if hour == 24:
            if minute or second or microsecond:
                raise ValueError("24:00:00 must have zero minutes, seconds, and fraction")
            hour = 0

        if hour > 23 or minute > 59 or second > 59:
            raise ValueError("Invalid time component")

        tz = m.group("tz")
        if tz:
            if tz == "Z":
                tzinfo = tzutc()
            else:
                sign = 1 if tz[0] == "+" else -1
                tz_body = tz[1:]
                if ":" in tz_body:
                    h_off, m_off = tz_body.split(":")
                    hour_off = int(h_off)
                    minute_off = int(m_off)
                else:
                    if len(tz_body) == 4:
                        hour_off = int(tz_body[:2])
                        minute_off = int(tz_body[2:])
                    elif len(tz_body) == 2:
                        hour_off = int(tz_body)
                        minute_off = 0
                    else:
                        raise ValueError(f"Invalid timezone offset: {tz}")
                offset_seconds = sign * (hour_off * 3600 + minute_off * 60)
                if offset_seconds == 0:
                    tzinfo = tzutc()
                else:
                    tzinfo = tzoffset(None, offset_seconds)

    return datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.
    A Matrix request typically contains a 'type' field that starts with 'm.'
    and a 'content' field. This function uses duck typing to check for these
    characteristics in either a dictionary or an object with attributes.
    """
    try:
        # Handle dictionary-like requests
        if isinstance(request, dict):
            t = request.get("type")
            if isinstance(t, str) and t.startswith("m."):
                # Optional: ensure 'content' key exists
                return "content" in request
        # Handle object-like requests
        else:
            t = getattr(request, "type", None)
            if isinstance(t, str) and t.startswith("m."):
                # Optional: ensure 'content' attribute exists
                return hasattr(request, "content")
    except Exception:
        # Any unexpected error should result in False
        pass
    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    D* nodes expect an ISO‑8601 string in UTC, with a trailing 'Z'.
    If the datetime is naive, it is formatted without a timezone.
    """
    # If the datetime is naive, just format it.
    if dt.tzinfo is None:
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    # Convert to UTC by subtracting the offset.
    offset = dt.utcoffset()
    if offset is None:
        # Treat as naive if offset cannot be determined.
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    utc_dt = dt - offset
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        # Attempt to use urllib.request without importing at module level
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # A tag must be non-empty, start with a letter, and contain only
    # letters, digits, underscores, or hyphens.  Tags are limited to 30
    # characters to avoid overly long identifiers.
    if not tag or len(tag) > 30:
        return False
    import re
    pattern = re.compile(r'^[A-Za-z][A-Za-z0-9_-]*$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    for child in node:
        result[child.tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'."
        )

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default NodeInfo endpoint path
    if document_path is None:
        document_path = "/nodeinfo/2.0"

    # Ensure the path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Build the full URL to the NodeInfo endpoint
    base = url.rstrip("/")
    href = f"{base}{document_path}"

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    import base64
    try:
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature
    except Exception:
        # cryptography library not available
        return False

    # Load the public key (PEM or DER)
    pub_key = None
    if isinstance(public_key, bytes):
        key_bytes = public_key
    else:
        key_bytes = public_key.encode() if isinstance(public_key, str) else public_key
    try:
        pub_key = serialization.load_pem_public_key(key_bytes)
    except Exception:
        try:
            pub_key = serialization.load_der_public_key(key_bytes)
        except Exception:
            return False

    # Prepare the document bytes
    if isinstance(doc, str):
        doc_bytes = doc.encode('utf-8')
    else:
        doc_bytes = doc

    # Prepare the signature bytes
    if isinstance(signature, str):
        try:
            signature_bytes = base64.b64decode(signature)
        except Exception:
            return False
    else:
        signature_bytes = signature

    # Verify the signature
    try:
        pub_key.verify(
            signature_bytes,
            doc_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except InvalidSignature:
        return False
    except Exception:
        return False

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        from urllib.parse import urlencode
        from urllib.request import urlopen, Request
        from urllib.error import URLError, HTTPError
    except Exception:
        return None

    if '@' not in handle:
        return None

    acct = f'acct:{handle}'
    _, domain = handle.split('@', 1)
    base_url = f'https://{domain}/.well-known/webfinger'
    query = urlencode({'resource': acct})
    url = f'{base_url}?{query}'

    req = Request(url, headers={'Accept': 'application/jrd+json'})
    try:
        with urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return None
            data = resp.read()
            try:
                return data.decode('utf-8')
            except Exception:
                return data.decode('latin1')
    except (HTTPError, URLError, Exception):
        return None

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file paths from the given directories, optionally filtered by a substring."""
    import os
    result = []
    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        for entry in os.listdir(dir_path):
            full_path = os.path.join(dir_path, entry)
            if os.path.isfile(full_path):
                if spec_option is None or spec_option in entry:
                    result.append(full_path)
    return result

