@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided")

        # Import yaml lazily to avoid global imports
        try:
            import yaml
        except ImportError as exc:
            raise IRValidatorException("PyYAML is required to load YAML files") from exc

        # Determine required fields; subclasses may override REQUIRED_FIELDS
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])

        try:
            with open(yaml_file, "r", encoding="utf-8") as fh:
                data = yaml.safe_load(fh)
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
        except yaml.YAMLError as exc:
            raise IRValidatorException(f"Error parsing YAML file: {yaml_file}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a top-level mapping")

        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in YAML file: {', '.join(missing)}"
            )

        return data

def _include_groups(self, parser_dict):
    """
    Resolve the ``include`` directive in a spec dictionary.

    The directive may be a single file path, a list of file paths, a dictionary of
    key/value pairs, or a list of such dictionaries.  The method merges the
    included content into ``parser_dict`` and removes the ``include`` key.
    It also recursively resolves nested ``include`` directives.

    Parameters
    ----------
    parser_dict : dict
        The dictionary representing the parsed spec file.

    Returns
    -------
    dict
        The dictionary with all ``include`` directives resolved.
    """
    # Import modules lazily to avoid top‑level imports
    import os
    import json
    try:
        import yaml
    except Exception:
        yaml = None

    def _load_file(path):
        """Load a YAML or JSON file and return its contents as a dict."""
        if not os.path.exists(path):
            return {}
        with open(path, "r", encoding="utf-8") as f:
            if yaml:
                return yaml.safe_load(f) or {}
            else:
                return json.load(f)

    def _merge(target, source):
        """Merge source dict into target dict, overriding existing keys."""
        for k, v in source.items():
            target[k] = v

    if not isinstance(parser_dict, dict):
        return parser_dict

    # Resolve the top‑level include directive
    if "include" in parser_dict:
        inc = parser_dict.pop("include")

        # Handle a single file path
        if isinstance(inc, str):
            inc_data = _load_file(inc)
            _merge(parser_dict, self._include_groups(inc_data))

        # Handle a dictionary of key/value pairs
        elif isinstance(inc, dict):
            _merge(parser_dict, self._include_groups(inc))

        # Handle a list of includes
        elif isinstance(inc, list):
            for item in inc:
                if isinstance(item, str):
                    inc_data = _load_file(item)
                    _merge(parser_dict, self._include_groups(inc_data))
                elif isinstance(item, dict):
                    _merge(parser_dict, self._include_groups(item))

    # Recursively resolve nested includes
    for key, value in list(parser_dict.items()):
        if isinstance(value, dict):
            parser_dict[key] = self._include_groups(value)
        elif isinstance(value, list):
            parser_dict[key] = [
                self._include_groups(v) if isinstance(v, dict) else v
                for v in value
            ]

    return parser_dict

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    Returns a dictionary mapping argument names to their resolved default values.
    """
    defaults = {}
    # Retrieve the list of argument specifications from the spec.
    spec_args = getattr(self, "spec", {}).get("arguments", [])
    for arg in spec_args:
        # Each argument spec should contain a 'name' key.
        name = arg.get("name")
        if not name:
            continue

        # Priority order: explicit default in spec -> environment variable -> config value -> None
        value = arg.get("default")

        if value is None:
            env_var = arg.get("env")
            if env_var:
                import os
                value = os.getenv(env_var)

        if value is None:
            config_key = arg.get("config")
            if config_key and hasattr(self, "config"):
                value = getattr(self, "config").get(config_key)

        defaults[name] = value

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Normalize the argument name by stripping leading dashes
    name = argument_name.lstrip('-')
    # Retrieve the command specification
    cmd_spec = self.commands.get(command_name)
    if cmd_spec is None:
        raise KeyError(f"Command '{command_name}' not found.")
    # Helper to search in a collection of option specs
    def find_in_collection(collection):
        if isinstance(collection, dict):
            return collection.get(name)
        if isinstance(collection, list):
            for item in collection:
                # Support dict or object with name/short/long attributes
                if isinstance(item, dict):
                    if item.get('name') == name or item.get('short') == name or item.get('long') == name:
                        return item
                else:
                    if getattr(item, 'name', None) == name or getattr(item, 'short', None) == name or getattr(item, 'long', None) == name:
                        return item
        return None
    # Search in options
    if isinstance(cmd_spec, dict):
        options = cmd_spec.get('options')
        if options is not None:
            spec = find_in_collection(options)
            if spec is not None:
                return spec
        # Some specs may store arguments under 'arguments'
        args = cmd_spec.get('arguments')
        if args is not None:
            spec = find_in_collection(args)
            if spec is not None:
                return spec
    else:
        # Object based spec
        options = getattr(cmd_spec, 'options', None)
        if options is not None:
            spec = find_in_collection(options)
            if spec is not None:
                return spec
        args = getattr(cmd_spec, 'arguments', None)
        if args is not None:
            spec = find_in_collection(args)
            if spec is not None:
                return spec
    # If not found, return None
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Convert args to a dictionary if possible
    if isinstance(args, dict):
        arg_dict = args
    elif hasattr(args, "__dict__"):
        arg_dict = vars(args)
    elif isinstance(args, (list, tuple)):
        try:
            arg_dict = dict(args)
        except Exception:
            return []
    else:
        return []

    silent = []
    for key, value in arg_dict.items():
        if value is None or value == "" or (
            isinstance(value, (list, tuple, set, dict)) and not value
        ):
            silent.append(key)
    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        # Skip if no condition specified
        if 'required_when' not in opt:
            continue
        cond = opt['required_when']
        # Helper to evaluate a single condition
        def eval_cond(c):
            try:
                if isinstance(c, str):
                    # Evaluate string expression with args as local variables
                    return bool(eval(c, {}, args))
                elif callable(c):
                    return bool(c(args))
                else:
                    # Unsupported condition type; treat as False
                    return False
            except Exception:
                # Any error in evaluation means condition not met
                return False
        # If condition is a list, any True triggers requirement
        if isinstance(cond, (list, tuple)):
            if any(eval_cond(c) for c in cond):
                required.append(opt.get('name'))
        else:
            if eval_cond(cond):
                required.append(opt.get('name'))
    return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Expect args to be a mapping of argument names to values.
        # The maximum allowed lengths should be defined in self.max_lengths
        # as a mapping of argument names to integer limits.
        max_lengths = getattr(self, "max_lengths", {})
        for name, value in args.items():
            # Skip if no length constraint is defined for this argument
            if name not in max_lengths:
                continue
            # Skip if the value is None (no length to check)
            if value is None:
                continue
            try:
                length = len(value)
            except Exception:
                # If the value has no length, skip or raise an error
                # Here we choose to skip to avoid breaking on non-iterables
                continue
            if length > max_lengths[name]:
                raise ValueError(
                    f"Argument '{name}' length {length} exceeds maximum allowed {max_lengths[name]}."
                )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Determine how to access values from args (dict or Namespace-like)
        def get_value(name):
            if isinstance(args, dict):
                return args.get(name)
            return getattr(args, name, None)

        for name, definition in getattr(self, "arguments", {}).items():
            # Skip if the argument is not present in the supplied args
            if name not in args if isinstance(args, dict) else not hasattr(args, name):
                continue

            value = get_value(name)
            # Skip if no choices are defined for this argument
            if "choices" not in definition:
                continue

            choices = definition["choices"]
            # If the value is a sequence, validate each element
            if isinstance(value, (list, tuple)):
                for v in value:
                    if v not in choices:
                        raise ValueError(
                            f"Invalid value for argument '{name}': {v}. "
                            f"Expected one of {choices}."
                        )
            else:
                if value not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value}. "
                        f"Expected one of {choices}."
                    )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Retrieve min and max values from the instance, if they exist
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    # If either bound is not defined, we cannot perform validation
    if min_val is None or max_val is None:
        return True

    # If args is a mapping, validate its values; otherwise, iterate directly
    if isinstance(args, dict):
        iterable = args.values()
    else:
        iterable = args

    # If args is None or empty, consider it valid
    if iterable is None:
        return True

    for val in iterable:
        # Skip non-numeric values silently
        try:
            if val < min_val or val > max_val:
                return False
        except TypeError:
            # If comparison fails, treat as invalid
            return False

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """
        Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Determine the desired type from spec_option
        desired_type = spec_option.get('type', 'string')

        # Helper for boolean conversion
        def _str_to_bool(val):
            if isinstance(val, bool):
                return val
            val_lower = val.lower()
            if val_lower in ('yes', 'true', 't', 'y', '1'):
                return True
            if val_lower in ('no', 'false', 'f', 'n', '0'):
                return False
            raise ValueError(f"Invalid boolean value for option '{option_name}': {val}")

        # Helper for list conversion (comma separated)
        def _to_list(val):
            if isinstance(val, list):
                return val
            return [item.strip() for item in val.split(',') if item.strip()]

        # Helper for dict conversion (key=value pairs, comma separated)
        def _to_dict(val):
            if isinstance(val, dict):
                return val
            result = {}
            for pair in val.split(','):
                if '=' not in pair:
                    raise ValueError(f"Invalid dict entry for option '{option_name}': {pair}")
                key, value = pair.split('=', 1)
                result[key.strip()] = value.strip()
            return result

        # Helper for JSON conversion
        def _to_json(val):
            import json
            try:
                return json.loads(val)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Invalid JSON for option '{option_name}': {val}") from exc

        # Map the desired type to the corresponding conversion function
        type_map = {
            'int': int,
            'float': float,
            'bool': _str_to_bool,
            'list': _to_list,
            'dict': _to_dict,
            'json': _to_json,
            'string': str,
        }

        # Return the appropriate callable; default to identity if unknown
        return type_map.get(desired_type, lambda x: x)

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    i = 0
    while i < len(args):
        arg = args[i]
        # Handle long options
        if isinstance(arg, str) and arg.startswith("--"):
            # Split key and value if present
            if "=" in arg:
                key, val = arg[2:].split("=", 1)
            else:
                key = arg[2:]
                # If next token exists and is not an option, treat it as value
                if i + 1 < len(args) and not args[i + 1].startswith("-"):
                    val = args[i + 1]
                    i += 1
                else:
                    val = True
            # Determine if this is a control argument
            if key.startswith("control_"):
                control_args[key[len("control_") :]] = val
            else:
                nested_args[key] = val
        # Handle short options (e.g., -c)
        elif isinstance(arg, str) and arg.startswith("-") and not arg.startswith("--"):
            key = arg[1:]
            if i + 1 < len(args) and not args[i + 1].startswith("-"):
                val = args[i + 1]
                i += 1
            else:
                val = True
            # Treat short options starting with 'c' as control for simplicity
            if key.startswith("c"):
                control_args[key[1:]] = val
            else:
                nested_args[key] = val
        else:
            # Positional or unrecognized token: treat as a flag with True
            nested_args[arg] = True
        i += 1
    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # If extra_vars is a dict, just update
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # Otherwise, iterate over the list
    for item in extra_vars:
        # Handle string items of the form "key=value"
        if isinstance(item, str):
            if '=' in item:
                key, val = item.split('=', 1)
                key = key.strip()
                val = val.strip()
                # If the value contains commas, treat it as a list
                if ',' in val:
                    val = [v.strip() for v in val.split(',')]
                vars_dict[key] = val
        # Handle dict items
        elif isinstance(item, dict):
            vars_dict.update(item)
        # Handle nested lists/tuples of key=value strings
        elif isinstance(item, (list, tuple)):
            for sub in item:
                if isinstance(sub, str) and '=' in sub:
                    key, val = sub.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    if ',' in val:
                        val = [v.strip() for v in val.split(',')]
                    vars_dict[key] = val
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define parser‑specific type hints (extend as needed)
    parser_specific = {
        'main': {'debug': bool, 'timeout': int, 'verbose': bool},
        'virsh': {'memory': int, 'cpu': int, 'name': str},
        'ospd': {'port': int, 'verbose': bool, 'hosts': list},
    }

    for key, val in list(values_dict.items()):
        # Skip non‑string values
        if not isinstance(val, str):
            continue

        # Parser‑specific conversion
        if parser_name in parser_specific and key in parser_specific[parser_name]:
            target_type = parser_specific[parser_name][key]
            try:
                if target_type is bool:
                    values_dict[key] = val.lower() in ('true', '1', 'yes')
                elif target_type is list:
                    values_dict[key] = [v.strip() for v in val.split(',') if v.strip()]
                else:
                    values_dict[key] = target_type(val)
                continue
            except Exception:
                # Fall back to generic conversion if parser‑specific fails
                pass

        # Generic boolean conversion
        if val.lower() in ('true', 'false', '1', '0', 'yes', 'no'):
            values_dict[key] = val.lower() in ('true', '1', 'yes')
            continue

        # Integer conversion
        if val.lstrip('-').isdigit():
            values_dict[key] = int(val)
            continue

        # Float conversion
        try:
            float_val = float(val)
            values_dict[key] = float_val
            continue
        except ValueError:
            pass

        # List conversion (comma separated)
        if ',' in val:
            values_dict[key] = [v.strip() for v in val.split(',') if v.strip()]
            continue

        # Leave as string if no conversion applies
        values_dict[key] = val

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Find the spec file (prefer YAML over JSON)
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if not spec_file:
        return {}

    with open(spec_file, "r", encoding="utf-8") as f:
        if spec_file.endswith((".yaml", ".yml")):
            if yaml is None:
                raise RuntimeError("PyYAML is required to parse YAML spec files")
            data = yaml.safe_load(f)
        else:
            data = json.load(f)

    if not isinstance(data, dict):
        return {}

    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("root cannot be empty")
    # Normalize root by stripping trailing path separators
    root_norm = root.rstrip('/\\')
    if not path.startswith(root_norm):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    rest = path[len(root_norm):]
    # After the root, the next character must be a separator or the string must end
    if rest and not rest[0] in ('/', '\\'):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    # Remove a leading separator from the remainder, if present
    if rest.startswith('/') or rest.startswith('\\'):
        rest = rest[1:]
    return rest
